"""
Core program model for static analysis.

Provides data structures representing simplified Java-like programs:
classes, methods, statements, variables, and types. This model serves
as the input representation that analysis tools operate on.
"""

import json
from dataclasses import dataclass, field
from typing import Any


@dataclass
class Type:
    name: str
    is_primitive: bool = False
    is_array: bool = False
    element_type: str | None = None

    def __hash__(self):
        return hash(self.name)

    def __eq__(self, other):
        if not isinstance(other, Type):
            return NotImplemented
        return self.name == other.name


@dataclass
class Variable:
    name: str
    var_type: Type
    is_parameter: bool = False
    param_index: int = -1

    def __hash__(self):
        return hash(self.name)

    def __eq__(self, other):
        if not isinstance(other, Variable):
            return NotImplemented
        return self.name == other.name


@dataclass
class FieldRef:
    base: str
    field_name: str
    field_type: Type
    declaring_class: str


@dataclass
class MethodSignature:
    class_name: str
    method_name: str
    param_types: list[str]
    return_type: str

    def full_signature(self) -> str:
        params = ", ".join(self.param_types)
        return f"<{self.class_name}: {self.return_type} {self.method_name}({params})>"

    def __hash__(self):
        return hash(self.full_signature())

    def __eq__(self, other):
        if not isinstance(other, MethodSignature):
            return NotImplemented
        return self.full_signature() == other.full_signature()


@dataclass
class Statement:
    stmt_id: int
    kind: str  # "assign", "call", "return", "if", "identity", "new", "field_store", "field_load", "nop"
    line_number: int = 0
    lhs: str | None = None
    rhs: str | None = None
    rhs_vars: list[str] = field(default_factory=list)
    callee: MethodSignature | None = None
    args: list[str] = field(default_factory=list)
    receiver: str | None = None
    condition: str | None = None
    true_target: int | None = None
    false_target: int | None = None
    field_ref: FieldRef | None = None
    is_source: bool = False
    is_sink: bool = False
    source_category: str | None = None
    sink_category: str | None = None
    metadata: dict[str, Any] = field(default_factory=dict)


@dataclass
class MethodBody:
    locals: list[Variable]
    statements: list[Statement]
    this_local: str | None = None
    param_locals: list[str] = field(default_factory=list)
    trap_handlers: list[dict] = field(default_factory=list)


@dataclass
class Method:
    signature: MethodSignature
    body: MethodBody | None = None
    is_static: bool = False
    is_abstract: bool = False
    is_constructor: bool = False
    is_entry_point: bool = False
    access: str = "public"


@dataclass
class ClassDef:
    name: str
    super_class: str | None = "java.lang.Object"
    interfaces: list[str] = field(default_factory=list)
    fields: list[dict] = field(default_factory=list)
    methods: list[Method] = field(default_factory=list)
    is_interface: bool = False
    is_abstract: bool = False
    is_library: bool = False
    is_android_component: bool = False
    component_type: str | None = None  # "activity", "service", "receiver", "provider"


@dataclass
class Program:
    name: str
    classes: list[ClassDef]
    entry_points: list[MethodSignature] = field(default_factory=list)
    expected_leaks: list[dict] = field(default_factory=list)
    source_sink_spec: dict = field(default_factory=dict)
    metadata: dict[str, Any] = field(default_factory=dict)


def _parse_type(t: str | dict) -> Type:
    if isinstance(t, str):
        prims = {"int", "float", "double", "boolean", "char", "byte", "short", "long", "void"}
        is_array = t.endswith("[]")
        base = t.rstrip("[]")
        return Type(name=t, is_primitive=base in prims, is_array=is_array,
                     element_type=base if is_array else None)
    return Type(name=t["name"], is_primitive=t.get("is_primitive", False),
                is_array=t.get("is_array", False), element_type=t.get("element_type"))


def _parse_field_ref(d: dict | None) -> FieldRef | None:
    if d is None:
        return None
    return FieldRef(base=d["base"], field_name=d["field_name"],
                    field_type=_parse_type(d.get("field_type", "java.lang.Object")),
                    declaring_class=d.get("declaring_class", ""))


def _parse_method_sig(d: dict | None) -> MethodSignature | None:
    if d is None:
        return None
    return MethodSignature(class_name=d["class_name"], method_name=d["method_name"],
                           param_types=d.get("param_types", []),
                           return_type=d.get("return_type", "void"))


def _parse_statement(d: dict) -> Statement:
    return Statement(
        stmt_id=d["stmt_id"], kind=d["kind"], line_number=d.get("line_number", 0),
        lhs=d.get("lhs"), rhs=d.get("rhs"), rhs_vars=d.get("rhs_vars", []),
        callee=_parse_method_sig(d.get("callee")), args=d.get("args", []),
        receiver=d.get("receiver"), condition=d.get("condition"),
        true_target=d.get("true_target"), false_target=d.get("false_target"),
        field_ref=_parse_field_ref(d.get("field_ref")),
        is_source=d.get("is_source", False), is_sink=d.get("is_sink", False),
        source_category=d.get("source_category"), sink_category=d.get("sink_category"),
        metadata=d.get("metadata", {}),
    )


def _parse_variable(d: dict) -> Variable:
    return Variable(name=d["name"], var_type=_parse_type(d.get("type", "java.lang.Object")),
                    is_parameter=d.get("is_parameter", False),
                    param_index=d.get("param_index", -1))


def _parse_body(d: dict | None) -> MethodBody | None:
    if d is None:
        return None
    return MethodBody(
        locals=[_parse_variable(v) for v in d.get("locals", [])],
        statements=[_parse_statement(s) for s in d.get("statements", [])],
        this_local=d.get("this_local"),
        param_locals=d.get("param_locals", []),
        trap_handlers=d.get("trap_handlers", []),
    )


def _parse_method(d: dict) -> Method:
    return Method(
        signature=_parse_method_sig(d["signature"]),
        body=_parse_body(d.get("body")),
        is_static=d.get("is_static", False),
        is_abstract=d.get("is_abstract", False),
        is_constructor=d.get("is_constructor", False),
        is_entry_point=d.get("is_entry_point", False),
        access=d.get("access", "public"),
    )


def _parse_class(d: dict) -> ClassDef:
    return ClassDef(
        name=d["name"], super_class=d.get("super_class", "java.lang.Object"),
        interfaces=d.get("interfaces", []),
        fields=d.get("fields", []),
        methods=[_parse_method(m) for m in d.get("methods", [])],
        is_interface=d.get("is_interface", False),
        is_abstract=d.get("is_abstract", False),
        is_library=d.get("is_library", False),
        is_android_component=d.get("is_android_component", False),
        component_type=d.get("component_type"),
    )


def load_program(path: str) -> Program:
    with open(path) as f:
        data = json.load(f)
    return Program(
        name=data["name"],
        classes=[_parse_class(c) for c in data["classes"]],
        entry_points=[_parse_method_sig(e) for e in data.get("entry_points", [])],
        expected_leaks=data.get("expected_leaks", []),
        source_sink_spec=data.get("source_sink_spec", {}),
        metadata=data.get("metadata", {}),
    )


def load_all_benchmarks(directory: str) -> list[Program]:
    import glob
    import os
    programs = []
    for path in sorted(glob.glob(os.path.join(directory, "*.json"))):
        programs.append(load_program(path))
    return programs
=== UTILS ===
"""Shared utility functions for the analysis framework."""

from __future__ import annotations

import time
from collections import defaultdict
from typing import TYPE_CHECKING

if TYPE_CHECKING:
    from program_model import ClassDef, MethodSignature, Program


def build_class_index(program: Program) -> dict[str, ClassDef]:
    return {c.name: c for c in program.classes}


def build_method_index(program: Program) -> dict[str, any]:
    index = {}
    for cls in program.classes:
        for method in cls.methods:
            key = method.signature.full_signature()
            index[key] = (cls, method)
    return index


def build_hierarchy(program: Program) -> dict[str, list[str]]:
    children: dict[str, list[str]] = defaultdict(list)
    for cls in program.classes:
        if cls.super_class:
            children[cls.super_class].append(cls.name)
        for iface in cls.interfaces:
            children[iface].append(cls.name)
    return dict(children)


def get_all_subclasses(hierarchy: dict[str, list[str]], class_name: str) -> set[str]:
    result = set()
    worklist = [class_name]
    while worklist:
        current = worklist.pop()
        for child in hierarchy.get(current, []):
            if child not in result:
                result.add(child)
                worklist.append(child)
    return result


class Timer:
    def __init__(self):
        self._start = None
        self._elapsed_ms = 0

    def __enter__(self):
        self._start = time.perf_counter()
        return self

    def __exit__(self, *args):
        self._elapsed_ms = (time.perf_counter() - self._start) * 1000

    @property
    def elapsed_ms(self) -> float:
        return self._elapsed_ms

