    def used_locals(self) -> list["Local"]:
        out: list[Local] = []
        for v in self.get_use_boxes():
            if isinstance(v, Local):
                out.append(v)
        if isinstance(self, Local):
            out.append(self)
        return out

    # -- value identity is structural, which keeps analyses deterministic --
    def _key(self) -> tuple:
        return (type(self).__name__, str(self))

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Value):
            return NotImplemented
        return self._key() == other._key()

    def __hash__(self) -> int:
        return hash(self._key())

    def __repr__(self) -> str:
        return str(self)


class Local(Value):
    """A Jimple local variable (``r0``, ``i1``, ...)."""

    __slots__ = ("name", "type", "is_parameter", "param_index")

    def __init__(
        self,
        name: str,
        var_type: Type | None = None,
        is_parameter: bool = False,
        param_index: int = -1,
    ) -> None:
        self.name = name
        self.type = var_type if var_type is not None else UNKNOWN_TYPE
        self.is_parameter = is_parameter
        self.param_index = param_index

    # Soot spells it ``getName`` / ``getType``.
    def get_name(self) -> str:
        return self.name

    def get_type(self) -> Type:
        return self.type

    def _key(self) -> tuple:
        return ("Local", self.name)

    def __str__(self) -> str:
        return self.name


class Constant(Value):
    """A compile-time constant."""

    __slots__ = ("value", "type", "text")

    def __init__(self, value: Any, const_type: Type | None = None, text: str | None = None) -> None:
        self.value = value
        self.type = const_type if const_type is not None else UNKNOWN_TYPE
        self.text = text if text is not None else str(value)

    def get_type(self) -> Type:
        return self.type

    def _key(self) -> tuple:
        return ("Constant", self.text)

    def __str__(self) -> str:
        return self.text


