class FieldSignature:
    """``<declaring.Class: type name>``."""

    __slots__ = ("declaring_class", "name", "type")

    def __init__(self, declaring_class: str, name: str, field_type: Type | None = None) -> None:
        self.declaring_class = declaring_class
        self.name = name
        self.type = field_type if field_type is not None else OBJECT_TYPE

    def full_signature(self) -> str:
        return "<%s: %s %s>" % (self.declaring_class, self.type.name, self.name)

    def get_sub_signature(self) -> str:
        return "%s %s" % (self.type.name, self.name)

    def __str__(self) -> str:
        return self.full_signature()

    def __repr__(self) -> str:
        return self.full_signature()

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, FieldSignature):
            return NotImplemented
        return self.full_signature() == other.full_signature()

    def __hash__(self) -> int:
        return hash(self.full_signature())


class SootField:
    """A field declared by a :class:`SootClass`."""

    __slots__ = ("name", "type", "declaring_class", "is_static", "is_final", "access")

    def __init__(
        self,
        name: str,
        field_type: Type,
        declaring_class: str,
        is_static: bool = False,
        is_final: bool = False,
        access: str = "public",
    ) -> None:
        self.name = name
        self.type = field_type
        self.declaring_class = declaring_class
        self.is_static = is_static
        self.is_final = is_final
        self.access = access

    def get_name(self) -> str:
        return self.name

    def get_type(self) -> Type:
        return self.type

    def get_signature(self) -> FieldSignature:
        return FieldSignature(self.declaring_class, self.name, self.type)

    def get_sub_signature(self) -> str:
        return "%s %s" % (self.type.name, self.name)

    def __str__(self) -> str:
        return self.get_signature().full_signature()

    def __repr__(self) -> str:
        return str(self)


