class BinopExpr(Expr):
    """``op1 <symbol> op2`` -- also used for the generic multi-operand case."""

    __slots__ = ("op1", "op2", "symbol", "type")

    def __init__(
        self, op1: Value, op2: Value, symbol: str = "+", result_type: Type | None = None
    ) -> None:
