        return self.symbol

    def get_type(self) -> Type:
        return self.type

    def get_use_boxes(self) -> list[Value]:
        return [self.op1, self.op2]

    def _key(self) -> tuple:
        return ("BinopExpr", str(self.op1), self.symbol, str(self.op2))

    def __str__(self) -> str:
        return "%s %s %s" % (self.op1, self.symbol, self.op2)


class ConditionExpr(BinopExpr):
    """A comparison used by :class:`IfStmt`."""

    __slots__ = ("text",)

    def __init__(
        self,
        op1: Value,
        op2: Value,
        symbol: str = "==",
        text: str | None = None,
    ) -> None:
        super().__init__(op1, op2, symbol, BOOLEAN_TYPE)
        self.text = text

    def _key(self) -> tuple:
        return ("ConditionExpr", self.text or str(super().__str__()))

    def __str__(self) -> str:
        if self.text:
            return self.text
        return "%s %s %s" % (self.op1, self.symbol, self.op2)


class PhiExpr(Expr):
    """An n-ary value merge -- used when a statement mentions several locals."""

    __slots__ = ("operands", "text", "type")

    def __init__(self, operands: list[Value], text: str = "", result_type: Type | None = None):
        self.operands = list(operands)
        self.text = text
        self.type = result_type if result_type is not None else UNKNOWN_TYPE

    def get_type(self) -> Type:
        return self.type

    def get_use_boxes(self) -> list[Value]:
        return list(self.operands)

    def _key(self) -> tuple:
        return ("PhiExpr", self.text, tuple(str(o) for o in self.operands))

    def __str__(self) -> str:
        return self.text or ("Phi(%s)" % ", ".join(str(o) for o in self.operands))


class SootMethodRef:
    """An unresolved reference to a method (Soot's ``SootMethodRef``)."""

    __slots__ = ("signature",)

    def __init__(self, signature: MethodSignature) -> None:
        self.signature = signature

    @property
    def declaring_class(self) -> str:
        return self.signature.class_name

    @property
    def name(self) -> str:
        return self.signature.method_name

    @property
    def parameter_types(self) -> list[str]:
        return list(self.signature.param_types)

    @property
    def return_type(self) -> str:
        return self.signature.return_type

    def get_signature(self) -> str:
        return self.signature.full_signature()

    def get_sub_signature(self) -> str:
        return sub_signature_of(self.signature)

    def resolve(self, scene: "Scene | None" = None) -> "SootMethod | None":
        scene = scene or Scene.v()
        return scene.get_method_unsafe(self.signature.full_signature())

    def __str__(self) -> str:
        return self.signature.full_signature()

    def __repr__(self) -> str:
        return str(self)

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, SootMethodRef):
            return NotImplemented
        return self.get_signature() == other.get_signature()

    def __hash__(self) -> int:
        return hash(self.get_signature())


def sub_signature_of(signature: MethodSignature) -> str:
    """``void foo(java.lang.String)`` -- the class-independent part."""
    return "%s %s(%s)" % (
        signature.return_type,
        signature.method_name,
        ", ".join(signature.param_types),
    )


class InvokeExpr(Expr):
    """Base class of the four Jimple invoke expressions."""

    __slots__ = ("method_ref", "args")

    def __init__(self, method_ref: SootMethodRef, args: list[Value] | None = None) -> None:
        self.method_ref = method_ref
        self.args = list(args or [])

    # -- Soot-style accessors ------------------------------------------------
    def get_method_ref(self) -> SootMethodRef:
        return self.method_ref

    def get_method(self) -> SootMethodRef:  # convenience alias
        return self.method_ref

    def get_signature(self) -> str:
        return self.method_ref.get_signature()

    def get_args(self) -> list[Value]:
        return list(self.args)

    def get_arg(self, index: int) -> Value | None:
        if 0 <= index < len(self.args):
            return self.args[index]
        return None

    def get_arg_count(self) -> int:
        return len(self.args)

    def get_type(self) -> Type:
        return make_type(self.method_ref.return_type)

    def get_base(self) -> Value | None:
        return None

    def get_use_boxes(self) -> list[Value]:
        return list(self.args)

    @property
    def kind(self) -> str:  # pragma: no cover - overridden
        return "invoke"

    def _key(self) -> tuple:
        return (
            type(self).__name__,
            str(self.get_base()),
            self.method_ref.get_signature(),
            tuple(str(a) for a in self.args),
        )

    def __str__(self) -> str:
        arglist = ", ".join(str(a) for a in self.args)
        return "%s %s(%s)" % (self.kind + "invoke", self.method_ref.get_signature(), arglist)


class InstanceInvokeExpr(InvokeExpr):
    """An invoke with a receiver."""

    __slots__ = ("base",)

    def __init__(
        self, base: Value, method_ref: SootMethodRef, args: list[Value] | None = None
    ) -> None:
        super().__init__(method_ref, args)
        self.base = base

    def get_base(self) -> Value:
        return self.base

    def get_use_boxes(self) -> list[Value]:
        return [self.base] + list(self.args)

    def __str__(self) -> str:
        arglist = ", ".join(str(a) for a in self.args)
        return "%sinvoke %s.%s(%s)" % (
            self.kind,
            self.base,
            self.method_ref.get_signature(),
            arglist,
        )


class VirtualInvokeExpr(InstanceInvokeExpr):
