# ---------------------------------------------------------------------------
# Jimple units (statements)
# ---------------------------------------------------------------------------


class Unit:
    """Base class of the Jimple unit (statement) hierarchy.

    Units carry a deterministic, globally unique ``uid`` so that they can be
    used as dictionary/set keys without relying on object identity hashing.
    """

    _next_uid = 0

    __slots__ = (
        "uid",
        "stmt_id",
        "line_number",
        "source_stmt",
        "owner",
        "_succ_ids",
        "metadata",
    )

    def __init__(
        self,
        stmt_id: int = -1,
        line_number: int = 0,
        source_stmt: Statement | None = None,
    ) -> None:
        Unit._next_uid += 1
        self.uid = Unit._next_uid
        self.stmt_id = stmt_id
        self.line_number = line_number
        self.source_stmt = source_stmt
        self.owner: "SootMethod | None" = None
        self._succ_ids: list[int] = []
        self.metadata: dict[str, Any] = dict(source_stmt.metadata) if source_stmt else {}

    # -- classification ------------------------------------------------------
    def branches(self) -> bool:
        """True if control may transfer somewhere other than the next unit."""
        return False

    def falls_through(self) -> bool:
        """True if control may continue with the textually next unit."""
        return True

    def is_return(self) -> bool:
        return False

    # -- def/use -------------------------------------------------------------
    def get_def_boxes(self) -> list[Value]:
        return []

    def get_use_boxes(self) -> list[Value]:
        return []

    def get_defined_local(self) -> Local | None:
        for v in self.get_def_boxes():
            if isinstance(v, Local):
                return v
        return None

    def get_used_locals(self) -> list[Local]:
        out: list[Local] = []
        seen: set[str] = set()
        for v in self.get_use_boxes():
            for loc in v.used_locals():
                if loc.name not in seen:
                    seen.add(loc.name)
                    out.append(loc)
        return out

    # -- invoke helpers ------------------------------------------------------
    def contains_invoke_expr(self) -> bool:
        return self.get_invoke_expr() is not None

    def get_invoke_expr(self) -> InvokeExpr | None:
        return None

    def contains_field_ref(self) -> bool:
        return self.get_field_ref() is not None

    def get_field_ref(self) -> FieldRefValue | None:
        return None

    def contains_array_ref(self) -> bool:
        return self.get_array_ref() is not None

    def get_array_ref(self) -> ArrayRef | None:
        return None

    # -- taint metadata forwarded from the neutral program model -------------
    @property
    def is_source(self) -> bool:
        return bool(self.source_stmt.is_source) if self.source_stmt else False

    @property
    def is_sink(self) -> bool:
        return bool(self.source_stmt.is_sink) if self.source_stmt else False

    @property
    def source_category(self) -> str | None:
        return self.source_stmt.source_category if self.source_stmt else None

    @property
    def sink_category(self) -> str | None:
        return self.source_stmt.sink_category if self.source_stmt else None

    @property
    def kind(self) -> str:
        return self.source_stmt.kind if self.source_stmt else "nop"

    def get_java_source_start_line_number(self) -> int:
        return self.line_number

    def replace_use(self, old: Value, new: Value) -> int:  # pragma: no cover - overridden
        return 0

    # -- identity ------------------------------------------------------------
    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Unit):
            return NotImplemented
        return self.uid == other.uid

    def __hash__(self) -> int:
        return hash(self.uid)

    def __repr__(self) -> str:
        return str(self)

    def __str__(self) -> str:  # pragma: no cover - overridden
        return "nop"


class Stmt(Unit):
    """Alias for :class:`Unit` -- Soot distinguishes ``Unit`` from ``Stmt``."""

    __slots__ = ()


class NopStmt(Stmt):
    __slots__ = ()

    def __str__(self) -> str:
        return "nop"


class DefinitionStmt(Stmt):
    """Base class of statements that define something (``left = right``)."""

    __slots__ = ("left_op", "right_op")

    def __init__(
        self,
        left_op: Value,
        right_op: Value,
        stmt_id: int = -1,
        line_number: int = 0,
        source_stmt: Statement | None = None,
    ) -> None:
        super().__init__(stmt_id, line_number, source_stmt)
        self.left_op = left_op
        self.right_op = right_op

    def get_left_op(self) -> Value:
        return self.left_op

    def get_right_op(self) -> Value:
        return self.right_op

    def get_def_boxes(self) -> list[Value]:
        return [self.left_op]

    def get_use_boxes(self) -> list[Value]:
        uses: list[Value] = [self.right_op]
        uses.extend(self.right_op.get_use_boxes())
        # ``a.f = x`` and ``a[i] = x`` *use* the base (and index) too.
        if isinstance(self.left_op, (InstanceFieldRef, ArrayRef)):
            uses.extend(self.left_op.get_use_boxes())
        return uses

    def get_def_locals(self) -> list[Local]:
        return [self.left_op] if isinstance(self.left_op, Local) else []

    def get_invoke_expr(self) -> InvokeExpr | None:
        return self.right_op if isinstance(self.right_op, InvokeExpr) else None

    def get_field_ref(self) -> FieldRefValue | None:
        if isinstance(self.left_op, FieldRefValue):
            return self.left_op
        if isinstance(self.right_op, FieldRefValue):
            return self.right_op
        return None

    def get_array_ref(self) -> ArrayRef | None:
        if isinstance(self.left_op, ArrayRef):
            return self.left_op
        if isinstance(self.right_op, ArrayRef):
            return self.right_op
        return None

    def replace_use(self, old: Value, new: Value) -> int:
        replaced = 0
        if self.right_op == old:
            self.right_op = new
            replaced += 1
        else:
            replaced += _replace_in_value(self.right_op, old, new)
        if isinstance(self.left_op, (InstanceFieldRef, ArrayRef)):
            replaced += _replace_in_value(self.left_op, old, new)
        return replaced

    def __str__(self) -> str:
        return "%s = %s" % (self.left_op, self.right_op)


class AssignStmt(DefinitionStmt):
    """``left = right``."""

    __slots__ = ()


class IdentityStmt(DefinitionStmt):
    """``r0 := @this`` / ``r1 := @parameter0``."""

    __slots__ = ()

    def get_use_boxes(self) -> list[Value]:
        # Identity statements do not *use* any local.
        return []

    def replace_use(self, old: Value, new: Value) -> int:
        return 0

    def __str__(self) -> str:
        return "%s := %s" % (self.left_op, self.right_op)


class InvokeStmt(Stmt):
    """A call whose result is discarded."""

    __slots__ = ("invoke_expr",)

    def __init__(
        self,
        invoke_expr: InvokeExpr,
        stmt_id: int = -1,
        line_number: int = 0,
        source_stmt: Statement | None = None,
    ) -> None:
        super().__init__(stmt_id, line_number, source_stmt)
        self.invoke_expr = invoke_expr

    def get_invoke_expr(self) -> InvokeExpr:
        return self.invoke_expr

    def get_use_boxes(self) -> list[Value]:
        return [self.invoke_expr] + self.invoke_expr.get_use_boxes()

    def replace_use(self, old: Value, new: Value) -> int:
        return _replace_in_value(self.invoke_expr, old, new)

    def __str__(self) -> str:
        return str(self.invoke_expr)


class ReturnStmt(Stmt):
    """``return op``."""

    __slots__ = ("op",)

    def __init__(
        self,
        op: Value,
        stmt_id: int = -1,
        line_number: int = 0,
        source_stmt: Statement | None = None,
    ) -> None:
        super().__init__(stmt_id, line_number, source_stmt)
        self.op = op

    def get_op(self) -> Value:
        return self.op

    def falls_through(self) -> bool:
        return False

    def is_return(self) -> bool:
        return True

    def get_use_boxes(self) -> list[Value]:
        return [self.op]

    def replace_use(self, old: Value, new: Value) -> int:
        if self.op == old:
            self.op = new
            return 1
        return 0

    def __str__(self) -> str:
        return "return %s" % self.op


class ReturnVoidStmt(Stmt):
    """``return``."""

    __slots__ = ()

    def falls_through(self) -> bool:
        return False

    def is_return(self) -> bool:
        return True

    def __str__(self) -> str:
        return "return"


class ThrowStmt(Stmt):
    """``throw op``."""

    __slots__ = ("op",)

    def __init__(
        self,
        op: Value,
        stmt_id: int = -1,
        line_number: int = 0,
        source_stmt: Statement | None = None,
    ) -> None:
        super().__init__(stmt_id, line_number, source_stmt)
        self.op = op

    def falls_through(self) -> bool:
        return False

    def get_use_boxes(self) -> list[Value]:
        return [self.op]

    def replace_use(self, old: Value, new: Value) -> int:
        if self.op == old:
            self.op = new
            return 1
        return 0

    def __str__(self) -> str:
        return "throw %s" % self.op


class BranchingStmt(Stmt):
    """Base class of ``goto``/``if``."""

    __slots__ = ("targets",)

    def __init__(
        self,
        stmt_id: int = -1,
        line_number: int = 0,
        source_stmt: Statement | None = None,
    ) -> None:
        super().__init__(stmt_id, line_number, source_stmt)
        self.targets: list[Unit] = []

    def branches(self) -> bool:
        return True

    def get_targets(self) -> list[Unit]:
        return list(self.targets)

    def set_target(self, index: int, unit: Unit) -> None:
        while len(self.targets) <= index:
            self.targets.append(unit)
        self.targets[index] = unit


class GotoStmt(BranchingStmt):
    """``goto target``."""

    __slots__ = ()

    def falls_through(self) -> bool:
        return False

    @property
    def target(self) -> Unit | None:
        return self.targets[0] if self.targets else None

    def get_target(self) -> Unit | None:
        return self.target

    def __str__(self) -> str:
        t = self.target
        return "goto %s" % ("stmt%d" % t.stmt_id if t is not None else "?")


class IfStmt(BranchingStmt):
    """``if condition goto target``.

    ``false_target`` is modelled explicitly because the neutral program model
    carries both branch destinations.
    """

    __slots__ = ("condition", "false_target")

    def __init__(
        self,
        condition: Value,
        stmt_id: int = -1,
        line_number: int = 0,
        source_stmt: Statement | None = None,
    ) -> None:
        super().__init__(stmt_id, line_number, source_stmt)
        self.condition = condition
        self.false_target: Unit | None = None

    def get_condition(self) -> Value:
        return self.condition

    @property
    def target(self) -> Unit | None:
        return self.targets[0] if self.targets else None

    def get_target(self) -> Unit | None:
        return self.target

    def falls_through(self) -> bool:
        return self.false_target is None

    def get_use_boxes(self) -> list[Value]:
        return [self.condition] + self.condition.get_use_boxes()

    def replace_use(self, old: Value, new: Value) -> int:
        if self.condition == old:
            self.condition = new
            return 1
        return _replace_in_value(self.condition, old, new)

    def __str__(self) -> str:
        t = self.target
        return "if %s goto %s" % (
            self.condition,
            "stmt%d" % t.stmt_id if t is not None else "?",
        )


def _replace_in_value(value: Value, old: Value, new: Value) -> int:
    """Structurally replace ``old`` with ``new`` inside ``value``."""
    replaced = 0
    if isinstance(value, InstanceInvokeExpr):
        if value.base == old:
            value.base = new
            replaced += 1
    if isinstance(value, InvokeExpr):
        for i, a in enumerate(value.args):
            if a == old:
                value.args[i] = new
                replaced += 1
    elif isinstance(value, InstanceFieldRef):
        if value.base == old:
            value.base = new
            replaced += 1
    elif isinstance(value, ArrayRef):
        if value.base == old:
            value.base = new
            replaced += 1
        if value.index == old:
            value.index = new
            replaced += 1
    elif isinstance(value, CastExpr):
        if value.op == old:
            value.op = new
            replaced += 1
    elif isinstance(value, InstanceOfExpr):
        if value.op == old:
            value.op = new
            replaced += 1
    elif isinstance(value, PhiExpr):
        for i, o in enumerate(value.operands):
            if o == old:
                value.operands[i] = new
                replaced += 1
    elif isinstance(value, BinopExpr):
        if value.op1 == old:
            value.op1 = new
            replaced += 1
        if value.op2 == old:
            value.op2 = new
            replaced += 1
    elif isinstance(value, NewArrayExpr):
        if value.size == old:
            value.size = new
            replaced += 1
    return replaced


