# ---------------------------------------------------------------------------
# Class hierarchy
# ---------------------------------------------------------------------------


class Hierarchy:
    """Sub/super-type queries plus Soot-style dispatch resolution.

    Everything is derived from the :class:`Scene` and cached; call
    :meth:`rebuild` after new classes are registered.
    """

    def __init__(self, scene: "Scene | None" = None) -> None:
        self.scene = scene if scene is not None else Scene.v()
        self._direct_subclasses: dict[str, list[str]] = {}
        self._direct_implementers: dict[str, list[str]] = {}
        self._sub_types: dict[str, list[str]] = {}
        self.rebuild()

    # -- construction --------------------------------------------------------
    def rebuild(self) -> "Hierarchy":
        self._direct_subclasses = {}
        self._direct_implementers = {}
        self._sub_types = {}
        for cls in self.scene.get_classes():
            if cls.super_class_name:
                bucket = self._direct_subclasses.setdefault(cls.super_class_name, [])
                if cls.name not in bucket:
                    bucket.append(cls.name)
            for iface in cls.interfaces:
                bucket = self._direct_implementers.setdefault(iface, [])
                if cls.name not in bucket:
                    bucket.append(cls.name)
        return self

    # -- raw relations -------------------------------------------------------
    def get_direct_subclasses_of(self, class_name: str) -> list[str]:
        return list(self._direct_subclasses.get(class_name, ()))

    def get_direct_implementers_of(self, interface_name: str) -> list[str]:
        return list(self._direct_implementers.get(interface_name, ()))

    def get_direct_sub_types_of(self, class_name: str) -> list[str]:
        out = self.get_direct_subclasses_of(class_name)
        for name in self.get_direct_implementers_of(class_name):
            if name not in out:
                out.append(name)
        return out

    def get_subclasses_of(self, class_name: str) -> list[str]:
        """Transitive subclasses (extends only), excluding ``class_name``."""
        out: list[str] = []
        seen: set[str] = {class_name}
        work = [class_name]
        while work:
            cur = work.pop(0)
            for child in self.get_direct_subclasses_of(cur):
                if child not in seen:
                    seen.add(child)
                    out.append(child)
                    work.append(child)
        return out

    def get_implementers_of(self, interface_name: str) -> list[str]:
        """Transitive implementers of an interface, excluding itself."""
        out: list[str] = []
        seen: set[str] = {interface_name}
        work = [interface_name]
        while work:
            cur = work.pop(0)
            for child in self.get_direct_sub_types_of(cur):
                if child not in seen:
                    seen.add(child)
                    out.append(child)
                    work.append(child)
        return out

    def get_sub_types_of(self, class_name: str) -> list[str]:
        """``class_name`` plus every transitive subclass/implementer."""
        cached = self._sub_types.get(class_name)
        if cached is not None:
            return list(cached)
        out: list[str] = [class_name]
        seen: set[str] = {class_name}
        work = [class_name]
        while work:
            cur = work.pop(0)
            for child in self.get_direct_sub_types_of(cur):
                if child not in seen:
                    seen.add(child)
                    out.append(child)
                    work.append(child)
        self._sub_types[class_name] = out
        return list(out)

    def get_super_classes_of(self, class_name: str) -> list[str]:
        """Strict super classes, nearest first."""
        out: list[str] = []
        seen: set[str] = {class_name}
        cur = self.scene.get_soot_class_unsafe(class_name)
        while cur is not None and cur.super_class_name:
            nxt = cur.super_class_name
            if nxt in seen:
                break
            seen.add(nxt)
            out.append(nxt)
            cur = self.scene.get_soot_class_unsafe(nxt)
        return out

    def get_super_classes_of_including(self, class_name: str) -> list[str]:
        return [class_name] + self.get_super_classes_of(class_name)

    def get_all_interfaces_of(self, class_name: str) -> list[str]:
        """Every interface transitively implemented by ``class_name``."""
        out: list[str] = []
        seen: set[str] = set()
        work = list(self.get_super_classes_of_including(class_name))
        while work:
            cur = work.pop(0)
            cls = self.scene.get_soot_class_unsafe(cur)
            if cls is None:
                continue
            for iface in cls.interfaces:
                if iface not in seen:
                    seen.add(iface)
                    out.append(iface)
                    work.append(iface)
        return out

    def is_class_subclass_of(self, child: str, parent: str) -> bool:
        if child == parent:
            return False
        return parent in self.get_super_classes_of(child)

    def is_class_subclass_of_including(self, child: str, parent: str) -> bool:
        return child == parent or self.is_class_subclass_of(child, parent)

    def is_sub_type_of(self, child: str, parent: str) -> bool:
        """Assignability in the ``child <: parent`` sense (classes + interfaces)."""
        if child == parent:
            return True
        if parent == OBJECT_CLASS:
            return True
        if parent in self.get_super_classes_of(child):
            return True
        return parent in self.get_all_interfaces_of(child)

    # -- dispatch ------------------------------------------------------------
    def resolve_concrete_dispatch(
        self, class_name: str, sub_sig: str
    ) -> "SootMethod | None":
        """Virtual dispatch on a *concrete* receiver type."""
        for cur in self.get_super_classes_of_including(class_name):
            cls = self.scene.get_soot_class_unsafe(cur)
            if cls is None:
                continue
            m = cls.get_method_by_sub_signature(sub_sig)
            if m is not None and not m.is_abstract:
                return m
        # Java 8 default methods.
        for iface in self.get_all_interfaces_of(class_name):
            cls = self.scene.get_soot_class_unsafe(iface)
            if cls is None:
                continue
            m = cls.get_method_by_sub_signature(sub_sig)
            if m is not None and not m.is_abstract:
                return m
        return None

    def resolve_abstract_dispatch(self, class_name: str, sub_sig: str) -> list["SootMethod"]:
        """CHA: every concrete implementation reachable from ``class_name``."""
        targets: list[SootMethod] = []
        seen: set[str] = set()
        for sub in self.get_sub_types_of(class_name):
            cls = self.scene.get_soot_class_unsafe(sub)
            if cls is None or cls.is_interface or cls.is_abstract:
                continue
            m = self.resolve_concrete_dispatch(sub, sub_sig)
            if m is not None and m.get_signature() not in seen:
                seen.add(m.get_signature())
                targets.append(m)
        if not targets:
            # The declared class itself may hold the only (possibly abstract)
            # declaration -- still useful for phantom-free call graphs.
            declared = self.resolve_concrete_dispatch(class_name, sub_sig)
            if declared is not None:
                targets.append(declared)
        return targets

    def resolve_special_dispatch(self, class_name: str, sub_sig: str) -> "SootMethod | None":
        """``invokespecial`` -- constructors, private and super calls."""
        return self.resolve_concrete_dispatch(class_name, sub_sig)

    def resolve_static_dispatch(self, class_name: str, sub_sig: str) -> "SootMethod | None":
        for cur in self.get_super_classes_of_including(class_name):
            cls = self.scene.get_soot_class_unsafe(cur)
            if cls is None:
                continue
            m = cls.get_method_by_sub_signature(sub_sig)
            if m is not None:
                return m
        return None

    # -- statistics ----------------------------------------------------------
    def get_depth(self, class_name: str) -> int:
        return len(self.get_super_classes_of(class_name))

    def stats(self) -> dict[str, int]:
        classes = self.scene.get_classes()
        return {
            "classes": len(classes),
            "edges": sum(len(v) for v in self._direct_subclasses.values())
            + sum(len(v) for v in self._direct_implementers.values()),
            "roots": len([c for c in classes if not c.super_class_name]),
            "leaves": len([c for c in classes if not self.get_direct_sub_types_of(c.name)]),
            "max_depth": max([self.get_depth(c.name) for c in classes], default=0),
        }


# ---------------------------------------------------------------------------
# Scene -- the global registry
# ---------------------------------------------------------------------------


class Scene:
    """Soot's global registry of classes, methods and entry points.

    A process-wide singleton reachable through :meth:`Scene.v`, matching
    Soot's API.  ``Scene.reset()`` installs a fresh instance, which keeps
    repeated analyses of different programs independent and deterministic.
    """

    _instance: "Scene | None" = None

    def __init__(self) -> None:
        self._classes: dict[str, SootClass] = {}
        self._methods: dict[str, SootMethod] = {}
        self._entry_points: list[SootMethod] = []
        self.program: Program | None = None
        self._hierarchy: Hierarchy | None = None
        self._call_graph: "CallGraph | None" = None
        self._point_to_analysis: Any = None
        self.phantom_class_names: list[str] = []
        self.phantom_method_signatures: list[str] = []

    # -- singleton -----------------------------------------------------------
    @classmethod
    def v(cls) -> "Scene":
        if cls._instance is None:
            cls._instance = Scene()
        return cls._instance

    @classmethod
    def reset(cls) -> "Scene":
        cls._instance = Scene()
        return cls._instance

    @classmethod
    def set_current(cls, scene: "Scene") -> "Scene":
        cls._instance = scene
        return scene

    # -- classes -------------------------------------------------------------
    def add_class(self, cls_obj: SootClass) -> SootClass:
        self._classes[cls_obj.name] = cls_obj
        return cls_obj

    # Soot spelling.
    add_basic_class = add_class

    def apply_class(self, cls_obj: SootClass) -> SootClass:
        return self.add_class(cls_obj)

    def contains_class(self, name: str) -> bool:
        return name in self._classes

    def get_soot_class(self, name: str) -> SootClass:
        cls_obj = self._classes.get(name)
        if cls_obj is None:
            raise KeyError("class not in scene: %s" % name)
        return cls_obj

    def get_soot_class_unsafe(
        self, name: str | None, create_phantom: bool = False
    ) -> SootClass | None:
        if name is None:
            return None
        cls_obj = self._classes.get(name)
        if cls_obj is None and create_phantom:
            return self.get_or_create_phantom_class(name)
        return cls_obj

    def get_or_create_phantom_class(self, name: str) -> SootClass:
        existing = self._classes.get(name)
        if existing is not None:
            return existing
        cls_obj = SootClass(
            name=name,
            super_class_name=None if name == OBJECT_CLASS else OBJECT_CLASS,
            is_library=True,
            is_phantom=True,
        )
        self.add_class(cls_obj)
        self.phantom_class_names.append(name)
        self._hierarchy = None
        return cls_obj

    def get_classes(self) -> list[SootClass]:
        return list(self._classes.values())

    def get_class_names(self) -> list[str]:
        return list(self._classes.keys())

    def get_application_classes(self) -> list[SootClass]:
        return [c for c in self._classes.values() if c.is_application_class()]

    def get_library_classes(self) -> list[SootClass]:
        return [c for c in self._classes.values() if c.is_library and not c.is_phantom]

    def get_phantom_classes(self) -> list[SootClass]:
        return [c for c in self._classes.values() if c.is_phantom]

    def get_android_components(self) -> list[SootClass]:
        return [c for c in self._classes.values() if c.is_android_component]

    # -- methods -------------------------------------------------------------
    def add_method(self, method: SootMethod) -> SootMethod:
        self._methods[method.get_signature()] = method
        return method

    def get_method(self, signature: str) -> SootMethod:
        m = self._methods.get(signature)
        if m is None:
            raise KeyError("method not in scene: %s" % signature)
        return m

    def get_method_unsafe(self, signature: str) -> SootMethod | None:
        return self._methods.get(signature)

    def contains_method(self, signature: str) -> bool:
        return signature in self._methods

    def get_methods(self) -> list[SootMethod]:
        return list(self._methods.values())

    def get_concrete_methods(self) -> list[SootMethod]:
        return [m for m in self._methods.values() if m.is_concrete()]

    def get_or_create_phantom_method(self, signature: MethodSignature) -> SootMethod:
        key = signature.full_signature()
        existing = self._methods.get(key)
        if existing is not None:
            return existing
        owner = self.get_or_create_phantom_class(signature.class_name)
        method = SootMethod(
            signature=signature,
            declaring_class=signature.class_name,
            is_static=False,
            is_abstract=True,
            is_constructor=signature.method_name == "<init>",
            is_phantom=True,
            is_library=True,
        )
        owner.add_method(method)
        self.add_method(method)
        self.phantom_method_signatures.append(key)
        return method

    def get_phantom_methods(self) -> list[SootMethod]:
        return [m for m in self._methods.values() if m.is_phantom]

    # -- entry points --------------------------------------------------------
    def set_entry_points(self, methods: Iterable[SootMethod]) -> None:
        self._entry_points = list(methods)

    def add_entry_point(self, method: SootMethod) -> None:
        if method not in self._entry_points:
            self._entry_points.append(method)

    def get_entry_points(self) -> list[SootMethod]:
        return list(self._entry_points)

    def has_entry_points(self) -> bool:
        return bool(self._entry_points)

    # -- derived structures --------------------------------------------------
    def get_active_hierarchy(self) -> Hierarchy:
        if self._hierarchy is None:
            self._hierarchy = Hierarchy(self)
        return self._hierarchy

    def set_active_hierarchy(self, hierarchy: Hierarchy) -> None:
        self._hierarchy = hierarchy

    def release_active_hierarchy(self) -> None:
        self._hierarchy = None

    def has_call_graph(self) -> bool:
        return self._call_graph is not None

    def get_call_graph(self) -> "CallGraph":
        if self._call_graph is None:
            raise RuntimeError("no call graph -- run CHATransformer.v().transform() first")
        return self._call_graph

    def set_call_graph(self, cg: "CallGraph") -> None:
        self._call_graph = cg

    def release_call_graph(self) -> None:
        self._call_graph = None

    # -- units ---------------------------------------------------------------
    def get_units(self) -> list[Unit]:
        out: list[Unit] = []
        for m in self._methods.values():
            out.extend(m.get_units())
        return out

    def get_fields(self) -> list[SootField]:
        out: list[SootField] = []
        for c in self._classes.values():
            out.extend(c.get_fields())
        return out

    def get_field_unsafe(self, declaring_class: str, field_name: str) -> SootField | None:
        hierarchy = self.get_active_hierarchy()
        for cur in hierarchy.get_super_classes_of_including(declaring_class):
            cls_obj = self._classes.get(cur)
            if cls_obj is None:
                continue
            f = cls_obj.get_field_by_name(field_name)
            if f is not None:
                return f
        return None

    # -- misc ----------------------------------------------------------------
    def stats(self) -> dict[str, int]:
        units = 0
        locals_ = 0
        bodies = 0
        for m in self._methods.values():
            body = m.get_active_body()
            if body is not None:
                bodies += 1
                units += len(body.units)
                locals_ += len(body.locals)
        return {
            "classes": len(self._classes),
            "application_classes": len(self.get_application_classes()),
            "library_classes": len(self.get_library_classes()),
            "phantom_classes": len(self.get_phantom_classes()),
            "methods": len(self._methods),
            "phantom_methods": len(self.get_phantom_methods()),
            "bodies": bodies,
            "units": units,
            "locals": locals_,
            "fields": len(self.get_fields()),
            "entry_points": len(self._entry_points),
        }

    def __str__(self) -> str:
        s = self.stats()
        return "Scene(classes=%d, methods=%d, units=%d)" % (
            s["classes"],
            s["methods"],
            s["units"],
        )

    def __repr__(self) -> str:
        return str(self)

