# ---------------------------------------------------------------------------
# IR construction: program_model -> Jimple
# ---------------------------------------------------------------------------

_INT_CHARS = frozenset("0123456789")

_BINARY_OPERATORS = (
    "<<",
    ">>",
    "&&",
    "||",
    "+",
    "-",
    "*",
    "/",
    "%",
    "&",
    "|",
    "^",
)

_COMPARISON_OPERATORS = ("==", "!=", "<=", ">=", "<", ">")


def _looks_like_int(text: str) -> bool:
    body = text[1:] if text[:1] in "+-" else text
    return bool(body) and all(ch in _INT_CHARS for ch in body)


def _looks_like_float(text: str) -> bool:
    body = text[1:] if text[:1] in "+-" else text
    if body.count(".") != 1:
        return False
    left, right = body.split(".")
    return (left == "" or all(c in _INT_CHARS for c in left)) and all(
        c in _INT_CHARS for c in right
    )


def parse_constant(text: str) -> Constant:
    """Best-effort conversion of a textual literal into a Jimple constant."""
    if text is None:
        return NullConstant()
    stripped = text.strip()
    if len(stripped) >= 2 and stripped[0] == '"' and stripped[-1] == '"':
        return StringConstant(stripped[1:-1], stripped)
    if stripped == "null":
        return NullConstant()
    if stripped in ("true", "false"):
        return BooleanConstant(stripped == "true", stripped)
    if _looks_like_int(stripped):
        return IntConstant(int(stripped), stripped)
    if stripped[-1:] in ("L", "l") and _looks_like_int(stripped[:-1]):
        return LongConstant(int(stripped[:-1]), stripped)
    if _looks_like_float(stripped):
        return DoubleConstant(float(stripped), stripped)
    if stripped[-1:] in ("f", "F", "d", "D") and _looks_like_float(stripped[:-1]):
        return DoubleConstant(float(stripped[:-1]), stripped)
    if stripped.endswith(".class"):
        return ClassConstant(stripped[: -len(".class")])
    return Constant(stripped, UNKNOWN_TYPE, stripped)


class IRBuilder:
    """Translates a :class:`program_model.Program` into Jimple.

    The builder is the ``jb`` (Jimple body) pack of this stack: it creates
    :class:`SootClass`, :class:`SootField`, :class:`SootMethod` and
    :class:`JimpleBody` objects, registers them in a :class:`Scene`, and
    resolves branch targets.
    """

    def __init__(self, scene: Scene | None = None) -> None:
        self.scene = scene if scene is not None else Scene.v()
        self.stats: dict[str, int] = {
            "classes": 0,
            "methods": 0,
            "bodies": 0,
            "units": 0,
            "locals": 0,
            "fields": 0,
            "constants": 0,
            "invoke_exprs": 0,
            "field_refs": 0,
            "unknown_kinds": 0,
        }
        self.warnings: list[str] = []

    # -- entry point ---------------------------------------------------------
    def build(self, program: Program) -> Scene:
        """Populate ``self.scene`` from ``program`` and return the scene."""
        self.scene.program = program
        for class_def in program.classes:
            self._build_class(class_def)
        # Phantom super types / interfaces keep the hierarchy total.
        for class_def in program.classes:
            if class_def.super_class:
                self.scene.get_or_create_phantom_class(class_def.super_class)
            for iface in class_def.interfaces:
                phantom = self.scene.get_or_create_phantom_class(iface)
                phantom.is_interface = True
        self.scene.release_active_hierarchy()
        # Bodies second so that every callee class already exists.
        for class_def in program.classes:
            soot_class = self.scene.get_soot_class(class_def.name)
            for method_def in class_def.methods:
                method = soot_class.get_method_by_sub_signature(
                    sub_signature_of(method_def.signature)
                )
                if method is None or method_def.body is None:
                    continue
                method.set_active_body(self._build_body(method, method_def.body))
                self.stats["bodies"] += 1
        self._resolve_entry_points(program)
        self.scene.release_active_hierarchy()
        return self.scene

    # -- classes and members -------------------------------------------------
    def _build_class(self, class_def: ClassDef) -> SootClass:
        existing = self.scene.get_soot_class_unsafe(class_def.name)
        if existing is not None and existing.is_phantom:
            # Upgrade a previously created phantom class in place.
            soot_class = existing
            soot_class.is_phantom = False
            if class_def.name in self.scene.phantom_class_names:
                self.scene.phantom_class_names.remove(class_def.name)
            soot_class.super_class_name = (
                None if class_def.name == OBJECT_CLASS else class_def.super_class
            )
            soot_class.interfaces = list(class_def.interfaces)
            soot_class.is_interface = class_def.is_interface
            soot_class.is_abstract = class_def.is_abstract
            soot_class.is_library = class_def.is_library
            soot_class.is_android_component = class_def.is_android_component
            soot_class.component_type = class_def.component_type
        else:
            soot_class = SootClass(
                name=class_def.name,
                super_class_name=class_def.super_class,
                interfaces=list(class_def.interfaces),
                is_interface=class_def.is_interface,
                is_abstract=class_def.is_abstract,
                is_library=class_def.is_library,
                is_phantom=False,
                is_android_component=class_def.is_android_component,
                component_type=class_def.component_type,
            )
            self.scene.add_class(soot_class)
        soot_class.source_class = class_def
        self.stats["classes"] += 1

        for field_def in class_def.fields:
            soot_field = SootField(
                name=field_def["name"],
                field_type=make_type(field_def.get("type", OBJECT_CLASS)),
                declaring_class=class_def.name,
                is_static=bool(field_def.get("is_static", False)),
                is_final=bool(field_def.get("is_final", False)),
                access=field_def.get("access", "public"),
            )
            soot_class.add_field(soot_field)
            self.stats["fields"] += 1

        for method_def in class_def.methods:
            method = SootMethod(
                signature=method_def.signature,
                declaring_class=class_def.name,
                is_static=method_def.is_static,
                is_abstract=method_def.is_abstract or method_def.body is None,
                is_constructor=method_def.is_constructor,
                is_entry_point=method_def.is_entry_point,
                access=method_def.access,
                is_phantom=False,
                is_library=class_def.is_library,
            )
            method.source_method = method_def
            soot_class.add_method(method)
            self.scene.add_method(method)
            self.stats["methods"] += 1
        return soot_class

    def _resolve_entry_points(self, program: Program) -> None:
        entries: list[SootMethod] = []
        for sig in program.entry_points:
            method = self.scene.get_method_unsafe(sig.full_signature())
            if method is not None and method not in entries:
                entries.append(method)
        for cls in self.scene.get_classes():
            for method in cls.get_methods():
                if method.is_entry_point and method not in entries:
                    entries.append(method)
        self.scene.set_entry_points(entries)

    # -- bodies --------------------------------------------------------------
    def _build_body(self, method: SootMethod, model_body: MethodBody) -> JimpleBody:
        body = JimpleBody(method=method)
        locals_by_name: dict[str, Local] = {}
        param_types = method.get_parameter_types()

        for var in model_body.locals:
            local = Local(
                name=var.name,
                var_type=make_type(var.var_type.name if var.var_type else OBJECT_CLASS),
                is_parameter=var.is_parameter,
                param_index=var.param_index,
            )
            locals_by_name[local.name] = local
            body.locals.append(local)
            self.stats["locals"] += 1

        def local_for(name: str, type_hint: str | None = None) -> Local:
            existing = locals_by_name.get(name)
            if existing is not None:
                return existing
            created = Local(name, make_type(type_hint or OBJECT_CLASS))
            locals_by_name[name] = created
            body.locals.append(created)
            self.stats["locals"] += 1
            return created

        if model_body.this_local:
            body.this_local = local_for(model_body.this_local, method.declaring_class)
        for index, param_name in enumerate(model_body.param_locals):
            hint = param_types[index] if index < len(param_types) else None
            param_local = local_for(param_name, hint)
            param_local.is_parameter = True
            param_local.param_index = index
            body.param_locals.append(param_local)
        body.traps = list(model_body.trap_handlers)

        branch_fixups: list[tuple[BranchingStmt, int | None, int | None]] = []
        for stmt in model_body.statements:
            unit = self._build_unit(stmt, locals_by_name, local_for, method, body)
            unit.owner = method
            body.units.append(unit)
            self.stats["units"] += 1
            if isinstance(unit, BranchingStmt):
                branch_fixups.append((unit, stmt.true_target, stmt.false_target))

        by_stmt_id = {u.stmt_id: u for u in body.units}
        for unit, true_target, false_target in branch_fixups:
            if true_target is not None and true_target in by_stmt_id:
                unit.set_target(0, by_stmt_id[true_target])
            if isinstance(unit, IfStmt) and false_target is not None:
                unit.false_target = by_stmt_id.get(false_target)
        return body

    def _build_unit(
        self,
        stmt: Statement,
        locals_by_name: dict[str, Local],
        local_for,
        method: SootMethod,
        body: JimpleBody,
    ) -> Unit:
        kind = stmt.kind
        if kind == "identity":
            return self._build_identity(stmt, local_for, method)
        if kind == "assign":
            left = local_for(stmt.lhs) if stmt.lhs else Local("$unknown")
            right = self._parse_rhs(stmt, locals_by_name, left.type)
            return AssignStmt(left, right, stmt.stmt_id, stmt.line_number, stmt)
        if kind == "new":
            left = local_for(stmt.lhs, stmt.rhs) if stmt.lhs else Local("$unknown")
            type_name = stmt.rhs or (left.type.name if left.type else OBJECT_CLASS)
            new_type = make_type(type_name)
            expr: Value = (
                NewArrayExpr(make_type(new_type.element_type or OBJECT_CLASS))
                if new_type.is_array
                else NewExpr(new_type)
            )
            return AssignStmt(left, expr, stmt.stmt_id, stmt.line_number, stmt)
        if kind == "call":
            return self._build_call(stmt, locals_by_name, local_for, method)
        if kind == "field_store":
            field_ref = self._make_field_ref(stmt.field_ref, locals_by_name, local_for)
            value = self._parse_rhs(stmt, locals_by_name, field_ref.get_type())
            self.stats["field_refs"] += 1
            return AssignStmt(field_ref, value, stmt.stmt_id, stmt.line_number, stmt)
        if kind == "field_load":
            left = local_for(stmt.lhs) if stmt.lhs else Local("$unknown")
            field_ref = self._make_field_ref(stmt.field_ref, locals_by_name, local_for)
            self.stats["field_refs"] += 1
            return AssignStmt(left, field_ref, stmt.stmt_id, stmt.line_number, stmt)
        if kind in ("array_store", "array_load"):
            return self._build_array_unit(stmt, locals_by_name, local_for)
        if kind == "return":
            if stmt.rhs is None:
                return ReturnVoidStmt(stmt.stmt_id, stmt.line_number, stmt)
            value = self._parse_rhs(stmt, locals_by_name, method.get_return_type())
            return ReturnStmt(value, stmt.stmt_id, stmt.line_number, stmt)
        if kind == "throw":
            value = self._parse_rhs(stmt, locals_by_name, make_type("java.lang.Throwable"))
            return ThrowStmt(value, stmt.stmt_id, stmt.line_number, stmt)
        if kind == "if":
            condition = self._parse_condition(stmt, locals_by_name)
            return IfStmt(condition, stmt.stmt_id, stmt.line_number, stmt)
        if kind == "goto":
            return GotoStmt(stmt.stmt_id, stmt.line_number, stmt)
        if kind == "nop":
            return NopStmt(stmt.stmt_id, stmt.line_number, stmt)
        self.stats["unknown_kinds"] += 1
        self.warnings.append(
            "unknown statement kind %r in %s (stmt%d)" % (kind, method.get_signature(), stmt.stmt_id)
        )
        return NopStmt(stmt.stmt_id, stmt.line_number, stmt)

    def _build_identity(self, stmt: Statement, local_for, method: SootMethod) -> IdentityStmt:
        rhs = (stmt.rhs or "").strip()
        if rhs == "@this":
            left = local_for(stmt.lhs, method.declaring_class)
            right: Value = ThisRef(make_type(method.declaring_class))
        elif rhs.startswith("@parameter"):
            digits = "".join(ch for ch in rhs[len("@parameter") :] if ch in _INT_CHARS)
            index = int(digits) if digits else 0
            params = method.get_parameter_types()
            param_type = make_type(params[index] if index < len(params) else OBJECT_CLASS)
            left = local_for(stmt.lhs, param_type.name)
            left.is_parameter = True
            left.param_index = index
            right = ParameterRef(index, param_type)
        elif rhs.startswith("@caughtexception"):
            left = local_for(stmt.lhs, "java.lang.Throwable")
            right = CaughtExceptionRef()
        else:
            left = local_for(stmt.lhs)
            right = parse_constant(rhs)
        return IdentityStmt(left, right, stmt.stmt_id, stmt.line_number, stmt)

    def _build_call(
        self, stmt: Statement, locals_by_name: dict[str, Local], local_for, method: SootMethod
    ) -> Unit:
        callee = stmt.callee
        if callee is None:
            self.stats["unknown_kinds"] += 1
            self.warnings.append(
                "call without callee in %s (stmt%d)" % (method.get_signature(), stmt.stmt_id)
            )
            return NopStmt(stmt.stmt_id, stmt.line_number, stmt)
        method_ref = SootMethodRef(callee)
        args: list[Value] = []
        for index, arg in enumerate(stmt.args):
            hint = (
                callee.param_types[index]
                if index < len(callee.param_types)
                else OBJECT_CLASS
            )
            args.append(self._parse_operand(arg, locals_by_name, make_type(hint)))
        declaring = self.scene.get_soot_class_unsafe(callee.class_name)
        resolved = None
        if declaring is not None:
            resolved = declaring.get_method_by_sub_signature(sub_signature_of(callee))
        is_static = stmt.receiver is None and (resolved is None or resolved.is_static)
        if resolved is not None and resolved.is_static:
            is_static = True
        invoke: InvokeExpr
        if is_static:
            invoke = StaticInvokeExpr(method_ref, args)
        else:
            base_name = stmt.receiver or "$unknownReceiver"
            base = locals_by_name.get(base_name)
            if base is None:
                base = local_for(base_name, callee.class_name)
            if callee.method_name == "<init>" or (
                resolved is not None and resolved.access == "private"
            ):
                invoke = SpecialInvokeExpr(base, method_ref, args)
            elif declaring is not None and declaring.is_interface:
                invoke = InterfaceInvokeExpr(base, method_ref, args)
            else:
                invoke = VirtualInvokeExpr(base, method_ref, args)
        self.stats["invoke_exprs"] += 1
        if stmt.lhs:
            left = local_for(stmt.lhs, callee.return_type)
            return AssignStmt(left, invoke, stmt.stmt_id, stmt.line_number, stmt)
        return InvokeStmt(invoke, stmt.stmt_id, stmt.line_number, stmt)

    def _build_array_unit(
        self, stmt: Statement, locals_by_name: dict[str, Local], local_for
    ) -> Unit:
        meta = stmt.metadata or {}
        base = local_for(meta.get("array_base") or (stmt.rhs_vars[0] if stmt.rhs_vars else "$arr"))
        index = self._parse_operand(str(meta.get("array_index", "0")), locals_by_name, INT_TYPE)
        array_ref = ArrayRef(base, index, make_type(base.type.element_type or OBJECT_CLASS))
        if stmt.kind == "array_store":
            value = self._parse_rhs(stmt, locals_by_name, array_ref.get_type())
            return AssignStmt(array_ref, value, stmt.stmt_id, stmt.line_number, stmt)
        left = local_for(stmt.lhs) if stmt.lhs else Local("$unknown")
        return AssignStmt(left, array_ref, stmt.stmt_id, stmt.line_number, stmt)

    def _make_field_ref(
        self, field_ref: FieldRef | None, locals_by_name: dict[str, Local], local_for
    ) -> FieldRefValue:
        if field_ref is None:
            return StaticFieldRef(FieldSignature("java.lang.Object", "$unknown", OBJECT_TYPE))
        declaring = field_ref.declaring_class or OBJECT_CLASS
        field_sig = FieldSignature(
            declaring, field_ref.field_name, make_type(field_ref.field_type.name)
        )
        self.scene.get_or_create_phantom_class(declaring)
        base_name = field_ref.base
        declared_field = None
        declaring_class = self.scene.get_soot_class_unsafe(declaring)
        if declaring_class is not None:
            declared_field = declaring_class.get_field_by_name(field_ref.field_name)
        is_static = declared_field is not None and declared_field.is_static
        if base_name in locals_by_name and not is_static:
            return InstanceFieldRef(locals_by_name[base_name], field_sig)
        if is_static or base_name == declaring or "." in (base_name or ""):
            return StaticFieldRef(field_sig)
        return InstanceFieldRef(local_for(base_name, declaring), field_sig)

    # -- operands ------------------------------------------------------------
    def _parse_operand(
        self, text: str | None, locals_by_name: dict[str, Local], type_hint: Type | None = None
    ) -> Value:
        if text is None:
            return NullConstant()
        stripped = text.strip()
        local = locals_by_name.get(stripped)
        if local is not None:
            return local
        constant = parse_constant(stripped)
        if type_hint is not None and isinstance(constant, Constant):
            if constant.type is UNKNOWN_TYPE or constant.type == UNKNOWN_TYPE:
                constant = Constant(constant.value, type_hint, constant.text)
        self.stats["constants"] += 1
        return constant

    def _parse_rhs(
        self, stmt: Statement, locals_by_name: dict[str, Local], type_hint: Type | None = None
    ) -> Value:
        text = (stmt.rhs or "").strip()
        used = [locals_by_name[v] for v in stmt.rhs_vars if v in locals_by_name]
        if text and text in locals_by_name:
            return locals_by_name[text]
        if len(used) == 1 and text and text != used[0].name:
            # e.g. ``(java.lang.String) r5`` or ``r5 + 1``
            symbol = _find_operator(text, _BINARY_OPERATORS)
            if symbol is not None:
                left, _, right = text.partition(symbol)
                return BinopExpr(
                    self._parse_operand(left, locals_by_name),
                    self._parse_operand(right, locals_by_name),
                    symbol,
                    type_hint,
                )
            if text.startswith("("):
                close = text.find(")")
                if close > 0:
                    return CastExpr(used[0], make_type(text[1:close].strip()))
            return PhiExpr(list(used), text, type_hint)
        if len(used) > 1:
            symbol = _find_operator(text, _BINARY_OPERATORS)
            if symbol is not None and len(used) == 2:
                return BinopExpr(used[0], used[1], symbol, type_hint)
            return PhiExpr(used, text, type_hint)
        if not text:
            return NullConstant()
        return self._parse_operand(text, locals_by_name, type_hint)

    def _parse_condition(self, stmt: Statement, locals_by_name: dict[str, Local]) -> Value:
        text = (stmt.condition or stmt.rhs or "").strip()
        symbol = _find_operator(text, _COMPARISON_OPERATORS)
        if symbol is not None:
            left, _, right = text.partition(symbol)
            return ConditionExpr(
                self._parse_operand(left, locals_by_name),
                self._parse_operand(right, locals_by_name),
                symbol,
                text,
            )
        used = [locals_by_name[v] for v in stmt.rhs_vars if v in locals_by_name]
        if len(used) == 1:
            return ConditionExpr(used[0], BooleanConstant(True), "==", text or None)
        if used:
            return PhiExpr(used, text, BOOLEAN_TYPE)
        return ConditionExpr(parse_constant(text or "true"), BooleanConstant(True), "==", text or None)

    # -- body cloning --------------------------------------------------------
    def rebuild_body(self, body: JimpleBody) -> JimpleBody:
        """Structural copy of ``body`` with fresh units and values."""
        return clone_body(body)


def _find_operator(text: str, operators: Iterable[str]) -> str | None:
    """Locate the first top-level operator from ``operators`` inside ``text``."""
    for op in operators:
        index = text.find(op)
        if index > 0 and index + len(op) < len(text):
            return op
    return None


def copy_value(value: Value) -> Value:
    """Deep copy of a Jimple value (locals and constants are shared)."""
    if isinstance(value, (Local, Constant, ThisRef, ParameterRef, CaughtExceptionRef)):
        return value
    if isinstance(value, InstanceFieldRef):
        return InstanceFieldRef(copy_value(value.base), value.field)
    if isinstance(value, StaticFieldRef):
        return StaticFieldRef(value.field)
    if isinstance(value, ArrayRef):
        return ArrayRef(copy_value(value.base), copy_value(value.index), value.type)
    if isinstance(value, NewExpr):
        return NewExpr(value.base_type)
    if isinstance(value, NewArrayExpr):
        return NewArrayExpr(value.base_type, copy_value(value.size))
    if isinstance(value, CastExpr):
        return CastExpr(copy_value(value.op), value.cast_type)
    if isinstance(value, InstanceOfExpr):
        return InstanceOfExpr(copy_value(value.op), value.check_type)
    if isinstance(value, ConditionExpr):
        return ConditionExpr(
            copy_value(value.op1), copy_value(value.op2), value.symbol, value.text
        )
    if isinstance(value, BinopExpr):
        return BinopExpr(copy_value(value.op1), copy_value(value.op2), value.symbol, value.type)
    if isinstance(value, PhiExpr):
        return PhiExpr([copy_value(o) for o in value.operands], value.text, value.type)
    if isinstance(value, StaticInvokeExpr):
        return StaticInvokeExpr(value.method_ref, [copy_value(a) for a in value.args])
    if isinstance(value, InstanceInvokeExpr):
        return type(value)(
            copy_value(value.base), value.method_ref, [copy_value(a) for a in value.args]
        )
    if isinstance(value, InvokeExpr):
        return InvokeExpr(value.method_ref, [copy_value(a) for a in value.args])
    return value


def clone_unit(unit: Unit) -> Unit:
    """Fresh unit with copied values; branch targets are *not* linked."""
    if isinstance(unit, IdentityStmt):
        return IdentityStmt(
            unit.left_op, copy_value(unit.right_op), unit.stmt_id, unit.line_number, unit.source_stmt
        )
    if isinstance(unit, AssignStmt):
        return AssignStmt(
            copy_value(unit.left_op),
            copy_value(unit.right_op),
            unit.stmt_id,
            unit.line_number,
            unit.source_stmt,
        )
    if isinstance(unit, InvokeStmt):
        return InvokeStmt(
            copy_value(unit.invoke_expr), unit.stmt_id, unit.line_number, unit.source_stmt
        )
    if isinstance(unit, ReturnStmt):
        return ReturnStmt(copy_value(unit.op), unit.stmt_id, unit.line_number, unit.source_stmt)
    if isinstance(unit, ReturnVoidStmt):
        return ReturnVoidStmt(unit.stmt_id, unit.line_number, unit.source_stmt)
    if isinstance(unit, ThrowStmt):
        return ThrowStmt(copy_value(unit.op), unit.stmt_id, unit.line_number, unit.source_stmt)
    if isinstance(unit, IfStmt):
        return IfStmt(copy_value(unit.condition), unit.stmt_id, unit.line_number, unit.source_stmt)
    if isinstance(unit, GotoStmt):
        return GotoStmt(unit.stmt_id, unit.line_number, unit.source_stmt)
    return NopStmt(unit.stmt_id, unit.line_number, unit.source_stmt)


def clone_body(body: JimpleBody) -> JimpleBody:
    """Structural copy of a :class:`JimpleBody` (used by optimisation passes)."""
    clone = JimpleBody(
        method=body.method,
        locals_=list(body.locals),
        this_local=body.this_local,
        param_locals=list(body.param_locals),
    )
    clone.traps = list(body.traps)
    mapping: dict[int, Unit] = {}
    for unit in body.units:
        fresh = clone_unit(unit)
        fresh.owner = unit.owner
        mapping[unit.uid] = fresh
        clone.units.append(fresh)
    for original, fresh in zip(body.units, clone.units):
        if isinstance(original, BranchingStmt) and isinstance(fresh, BranchingStmt):
            for index, target in enumerate(original.targets):
                mapped = mapping.get(target.uid)
                if mapped is not None:
                    fresh.set_target(index, mapped)
        if isinstance(original, IfStmt) and isinstance(fresh, IfStmt):
            if original.false_target is not None:
                fresh.false_target = mapping.get(original.false_target.uid)
    return clone

