# ---------------------------------------------------------------------------
# Intra-procedural control-flow graphs
# ---------------------------------------------------------------------------


class UnitGraph:
    """CFG over the units of one :class:`JimpleBody`."""

    def __init__(self, body: JimpleBody) -> None:
        self.body = body
        self._units: list[Unit] = list(body.units)
        self._succs: dict[int, list[Unit]] = {}
        self._preds: dict[int, list[Unit]] = {}
        self._build()

    # -- construction --------------------------------------------------------
    def _build(self) -> None:
        self._succs = {u.uid: [] for u in self._units}
        self._preds = {u.uid: [] for u in self._units}
        for index, unit in enumerate(self._units):
            for succ in self._compute_successors(index, unit):
                if succ is None:
                    continue
                if succ not in self._succs[unit.uid]:
                    self._succs[unit.uid].append(succ)
                bucket = self._preds.setdefault(succ.uid, [])
                if unit not in bucket:
                    bucket.append(unit)

    def _compute_successors(self, index: int, unit: Unit) -> list[Unit | None]:
        out: list[Unit | None] = []
        if unit.falls_through() and index + 1 < len(self._units):
            out.append(self._units[index + 1])
        if isinstance(unit, BranchingStmt):
            out.extend(unit.get_targets())
        if isinstance(unit, IfStmt) and unit.false_target is not None:
            out.append(unit.false_target)
        return out

    # -- Soot-style accessors ------------------------------------------------
    def get_body(self) -> JimpleBody:
        return self.body

    def get_successors_of(self, unit: Unit) -> list[Unit]:
        return list(self._succs.get(unit.uid, ()))

    def get_predecessors_of(self, unit: Unit) -> list[Unit]:
        return list(self._preds.get(unit.uid, ()))

    def get_heads(self) -> list[Unit]:
        if not self._units:
            return []
        heads = [self._units[0]]
        for unit in self._units[1:]:
            if not self._preds.get(unit.uid):
                # An unreachable unit is not a head in Soot, but trap handlers are.
                if unit.metadata.get("is_handler"):
                    heads.append(unit)
        return heads

    def get_tails(self) -> list[Unit]:
        return [u for u in self._units if not self._succs.get(u.uid)]

    def get_units(self) -> list[Unit]:
        return list(self._units)

    def size(self) -> int:
        return len(self._units)

    def edge_count(self) -> int:
        return sum(len(v) for v in self._succs.values())

    def get_reachable_units(self) -> list[Unit]:
        """Units reachable from the entry (plus trap handlers)."""
        reachable: list[Unit] = []
        seen: set[int] = set()
        work = list(self.get_heads())
        while work:
            unit = work.pop(0)
            if unit.uid in seen:
                continue
            seen.add(unit.uid)
            reachable.append(unit)
            work.extend(self.get_successors_of(unit))
        return [u for u in self._units if u.uid in seen] if reachable else []

    def __iter__(self) -> Iterator[Unit]:
        return iter(self._units)

    def __len__(self) -> int:
        return len(self._units)

    def __str__(self) -> str:
        sig = self.body.method.get_signature() if self.body.method else "<unknown>"
        return "UnitGraph(%s, units=%d, edges=%d)" % (sig, self.size(), self.edge_count())


class BriefUnitGraph(UnitGraph):
    """CFG without exceptional edges (Soot's default for most analyses)."""


class ExceptionalUnitGraph(UnitGraph):
    """CFG including edges from every protected unit to its trap handler."""

    def _build(self) -> None:
        super()._build()
        by_stmt_id = {u.stmt_id: u for u in self._units}
        for trap in self.body.traps:
            handler_id = trap.get("handler_stmt_id", trap.get("handler"))
            if handler_id is None:
                continue
            handler = by_stmt_id.get(handler_id)
            if handler is None:
                continue
            handler.metadata["is_handler"] = True
            begin = trap.get("begin_stmt_id", trap.get("begin"))
            end = trap.get("end_stmt_id", trap.get("end"))
            for unit in self._units:
                if begin is not None and unit.stmt_id < begin:
                    continue
                if end is not None and unit.stmt_id > end:
                    continue
                if handler not in self._succs[unit.uid]:
                    self._succs[unit.uid].append(handler)
                    self._preds.setdefault(handler.uid, []).append(unit)


# ---------------------------------------------------------------------------
# Generic intra-procedural data-flow analyses
# ---------------------------------------------------------------------------


class FlowAnalysis:
    """Worklist skeleton shared by the forward/backward analyses."""

    def __init__(self, graph: UnitGraph) -> None:
        self.graph = graph
        self.unit_to_before_flow: dict[int, set] = {}
        self.unit_to_after_flow: dict[int, set] = {}
        self.iterations = 0

    # -- lattice -------------------------------------------------------------
    def new_initial_flow(self) -> set:
        return set()

    def entry_initial_flow(self) -> set:
        return self.new_initial_flow()

    def merge(self, left: set, right: set) -> set:
        return left | right

    def flow_through(self, in_flow: set, unit: Unit) -> set:
        return set(in_flow)

    # -- results -------------------------------------------------------------
    def get_flow_before(self, unit: Unit) -> set:
        return self.unit_to_before_flow.get(unit.uid, set())

    def get_flow_after(self, unit: Unit) -> set:
        return self.unit_to_after_flow.get(unit.uid, set())


class ForwardFlowAnalysis(FlowAnalysis):
    def do_analysis(self) -> "ForwardFlowAnalysis":
        units = self.graph.get_units()
        for unit in units:
            self.unit_to_before_flow[unit.uid] = self.new_initial_flow()
            self.unit_to_after_flow[unit.uid] = self.new_initial_flow()
        head_uids = {u.uid for u in self.graph.get_heads()}
        worklist = list(units)
        while worklist:
            unit = worklist.pop(0)
            self.iterations += 1
            before = self.new_initial_flow()
            if unit.uid in head_uids:
                before = self.merge(before, self.entry_initial_flow())
            for pred in self.graph.get_predecessors_of(unit):
                before = self.merge(before, self.unit_to_after_flow[pred.uid])
            self.unit_to_before_flow[unit.uid] = before
            after = self.flow_through(before, unit)
            if after != self.unit_to_after_flow[unit.uid]:
                self.unit_to_after_flow[unit.uid] = after
                for succ in self.graph.get_successors_of(unit):
                    if succ not in worklist:
                        worklist.append(succ)
        return self


class BackwardFlowAnalysis(FlowAnalysis):
    def do_analysis(self) -> "BackwardFlowAnalysis":
        units = self.graph.get_units()
        for unit in units:
            self.unit_to_before_flow[unit.uid] = self.new_initial_flow()
            self.unit_to_after_flow[unit.uid] = self.new_initial_flow()
        tail_uids = {u.uid for u in self.graph.get_tails()}
        worklist = list(reversed(units))
        while worklist:
            unit = worklist.pop(0)
            self.iterations += 1
            after = self.new_initial_flow()
            if unit.uid in tail_uids:
                after = self.merge(after, self.entry_initial_flow())
            for succ in self.graph.get_successors_of(unit):
                after = self.merge(after, self.unit_to_before_flow[succ.uid])
            self.unit_to_after_flow[unit.uid] = after
            before = self.flow_through(after, unit)
            if before != self.unit_to_before_flow[unit.uid]:
                self.unit_to_before_flow[unit.uid] = before
                for pred in self.graph.get_predecessors_of(unit):
                    if pred not in worklist:
                        worklist.append(pred)
        return self


class ReachingDefinitions(ForwardFlowAnalysis):
    """Facts are ``(local name, defining unit)`` pairs."""

    def __init__(self, graph: UnitGraph) -> None:
        super().__init__(graph)
        self.do_analysis()

    def flow_through(self, in_flow: set, unit: Unit) -> set:
        defined = unit.get_defined_local()
        if defined is None:
            return set(in_flow)
        out = {fact for fact in in_flow if fact[0] != defined.name}
        out.add((defined.name, unit))
        return out


class SimpleLocalDefs:
    """``local x used at unit u`` -> the units that may define ``x``."""

    def __init__(self, graph: UnitGraph) -> None:
        self.graph = graph
        self._reaching = ReachingDefinitions(graph)
        self._at: dict[tuple[int, str], list[Unit]] = {}
        self._all: dict[str, list[Unit]] = {}
        for unit in graph:
            defined = unit.get_defined_local()
            if defined is not None:
                self._all.setdefault(defined.name, []).append(unit)
            before = self._reaching.get_flow_before(unit)
            for local in unit.get_used_locals():
                matches = [u for (name, u) in before if name == local.name]
                self._at[(unit.uid, local.name)] = sorted(matches, key=lambda u: u.uid)

    def get_defs_of_at(self, local: Local, unit: Unit) -> list[Unit]:
        return list(self._at.get((unit.uid, local.name), ()))

    def get_defs_of(self, local: Local | str) -> list[Unit]:
        name = local if isinstance(local, str) else local.name
        return list(self._all.get(name, ()))

    def def_count(self, local: Local | str) -> int:
        return len(self.get_defs_of(local))


class SimpleLocalUses:
    """The inverse of :class:`SimpleLocalDefs`."""

    def __init__(self, graph: UnitGraph, local_defs: SimpleLocalDefs | None = None) -> None:
        self.graph = graph
        self.local_defs = local_defs if local_defs is not None else SimpleLocalDefs(graph)
        self._uses: dict[int, list[tuple[Unit, Local]]] = {}
        for unit in graph:
            for local in unit.get_used_locals():
                for definition in self.local_defs.get_defs_of_at(local, unit):
                    self._uses.setdefault(definition.uid, []).append((unit, local))

    def get_uses_of(self, unit: Unit) -> list[tuple[Unit, Local]]:
        return list(self._uses.get(unit.uid, ()))

    def use_count(self, unit: Unit) -> int:
        return len(self._uses.get(unit.uid, ()))


class SimpleLiveLocals(BackwardFlowAnalysis):
    """Classic live-variable analysis over local names."""

    def __init__(self, graph: UnitGraph) -> None:
        super().__init__(graph)
        self.do_analysis()

    def flow_through(self, in_flow: set, unit: Unit) -> set:
        out = set(in_flow)
        defined = unit.get_defined_local()
        if defined is not None:
            out.discard(defined.name)
        for local in unit.get_used_locals():
            out.add(local.name)
        return out

    def get_live_locals_before(self, unit: Unit) -> set:
        return self.get_flow_before(unit)

    def get_live_locals_after(self, unit: Unit) -> set:
        return self.get_flow_after(unit)


# ---------------------------------------------------------------------------
# Call graph
# ---------------------------------------------------------------------------


class Kind:
    """Edge kinds, mirroring ``soot.jimple.toolkits.callgraph.Kind``."""

    INVALID = "invalid"
    STATIC = "static"
    VIRTUAL = "virtual"
    SPECIAL = "special"
    INTERFACE = "interface"
    CLINIT = "clinit"
    ENTRY = "entry"

    ALL = (STATIC, VIRTUAL, SPECIAL, INTERFACE, CLINIT, ENTRY)


class Edge:
    """A call-graph edge ``src --(src_unit)--> tgt``."""

    __slots__ = ("src", "src_unit", "tgt", "kind")

    def __init__(
        self,
        src: SootMethod | None,
        src_unit: Unit | None,
        tgt: SootMethod,
        kind: str = Kind.VIRTUAL,
    ) -> None:
        self.src = src
        self.src_unit = src_unit
        self.tgt = tgt
        self.kind = kind

    def get_src(self) -> SootMethod | None:
        return self.src

    def src_stmt(self) -> Unit | None:
        return self.src_unit

    def get_tgt(self) -> SootMethod:
        return self.tgt

    def get_kind(self) -> str:
        return self.kind

    def is_explicit(self) -> bool:
        return self.kind in (Kind.STATIC, Kind.VIRTUAL, Kind.SPECIAL, Kind.INTERFACE)

    def _key(self) -> tuple:
        return (
            self.src.get_signature() if self.src else "",
            self.src_unit.uid if self.src_unit else -1,
            self.tgt.get_signature(),
            self.kind,
        )

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Edge):
            return NotImplemented
        return self._key() == other._key()

    def __hash__(self) -> int:
        return hash(self._key())

    def __str__(self) -> str:
        where = "stmt%d" % self.src_unit.stmt_id if self.src_unit is not None else "-"
        return "%s -[%s@%s]-> %s" % (
            self.src.get_signature() if self.src else "<entry>",
            self.kind,
            where,
            self.tgt.get_signature(),
        )

    def __repr__(self) -> str:
        return str(self)


class CallGraph:
    """A set of :class:`Edge` objects with the usual indexes."""

    def __init__(self) -> None:
        self._edges: list[Edge] = []
        self._keys: set[tuple] = set()
        self._out: dict[str, list[Edge]] = {}
        self._in: dict[str, list[Edge]] = {}
        self._by_unit: dict[int, list[Edge]] = {}

    def add_edge(self, edge: Edge) -> bool:
        key = edge._key()
        if key in self._keys:
            return False
        self._keys.add(key)
        self._edges.append(edge)
        if edge.src is not None:
            self._out.setdefault(edge.src.get_signature(), []).append(edge)
        self._in.setdefault(edge.tgt.get_signature(), []).append(edge)
        if edge.src_unit is not None:
            self._by_unit.setdefault(edge.src_unit.uid, []).append(edge)
        return True

    # -- queries -------------------------------------------------------------
    def edges_out_of(self, method: SootMethod | str) -> list[Edge]:
        key = method if isinstance(method, str) else method.get_signature()
        return list(self._out.get(key, ()))

    def edges_into(self, method: SootMethod | str) -> list[Edge]:
        key = method if isinstance(method, str) else method.get_signature()
        return list(self._in.get(key, ()))

    def edges_out_of_unit(self, unit: Unit) -> list[Edge]:
        return list(self._by_unit.get(unit.uid, ()))

    def callees_of_unit(self, unit: Unit) -> list[SootMethod]:
        return [e.tgt for e in self.edges_out_of_unit(unit)]

    def callees_of(self, method: SootMethod | str) -> list[SootMethod]:
        out: list[SootMethod] = []
        seen: set[str] = set()
        for edge in self.edges_out_of(method):
            sig = edge.tgt.get_signature()
            if sig not in seen:
                seen.add(sig)
                out.append(edge.tgt)
        return out

    def callers_of(self, method: SootMethod | str) -> list[SootMethod]:
        out: list[SootMethod] = []
        seen: set[str] = set()
        for edge in self.edges_into(method):
            if edge.src is None:
                continue
            sig = edge.src.get_signature()
            if sig not in seen:
                seen.add(sig)
                out.append(edge.src)
        return out

    def call_sites_into(self, method: SootMethod | str) -> list[tuple[SootMethod, Unit]]:
        return [
            (e.src, e.src_unit)
            for e in self.edges_into(method)
            if e.src is not None and e.src_unit is not None
        ]

    def get_nodes(self) -> list[SootMethod]:
        out: list[SootMethod] = []
        seen: set[str] = set()
        for edge in self._edges:
            for method in (edge.src, edge.tgt):
                if method is None:
                    continue
                sig = method.get_signature()
                if sig not in seen:
                    seen.add(sig)
                    out.append(method)
        return out

    def get_edges(self) -> list[Edge]:
        return list(self._edges)

    def edges_by_kind(self, kind: str) -> list[Edge]:
        return [e for e in self._edges if e.kind == kind]

    def size(self) -> int:
        return len(self._edges)

    def is_reachable_from(self, entry: SootMethod, target: SootMethod) -> bool:
        return ReachableMethods(self, [entry]).contains(target)

    def __len__(self) -> int:
        return len(self._edges)

    def __iter__(self) -> Iterator[Edge]:
        return iter(self._edges)

    def __str__(self) -> str:
        return "CallGraph(edges=%d, nodes=%d)" % (self.size(), len(self.get_nodes()))


class ReachableMethods:
    """Transitive closure of a :class:`CallGraph` from a set of entry points."""

    def __init__(self, call_graph: CallGraph, entry_points: Iterable[SootMethod]) -> None:
        self.call_graph = call_graph
        self.entry_points = list(entry_points)
        self._order: list[SootMethod] = []
        self._seen: set[str] = set()
        self._update()

    def _update(self) -> None:
        work = list(self.entry_points)
        while work:
            method = work.pop(0)
            sig = method.get_signature()
            if sig in self._seen:
                continue
            self._seen.add(sig)
            self._order.append(method)
            for edge in self.call_graph.edges_out_of(method):
                if edge.tgt.get_signature() not in self._seen:
                    work.append(edge.tgt)

    def contains(self, method: SootMethod | str) -> bool:
        key = method if isinstance(method, str) else method.get_signature()
        return key in self._seen

    def listener(self) -> list[SootMethod]:
        return list(self._order)

    def get_reachable_methods(self) -> list[SootMethod]:
        return list(self._order)

    def size(self) -> int:
        return len(self._order)

    def __iter__(self) -> Iterator[SootMethod]:
        return iter(self._order)

    def __len__(self) -> int:
        return len(self._order)


class CHATransformer:
    """Builds a Class-Hierarchy-Analysis call graph for the whole scene."""

    _instance: "CHATransformer | None" = None

    def __init__(self) -> None:
        self.stats: dict[str, int] = {}

    @classmethod
    def v(cls) -> "CHATransformer":
        if cls._instance is None:
            cls._instance = CHATransformer()
        return cls._instance

    def transform(
        self, scene: Scene | None = None, call_graph: CallGraph | None = None
    ) -> CallGraph:
        scene = scene if scene is not None else Scene.v()
        hierarchy = scene.get_active_hierarchy()
        cg = call_graph if call_graph is not None else CallGraph()
        stats = {
            "call_sites": 0,
            "resolved_call_sites": 0,
            "phantom_call_sites": 0,
            "phantom_edges": 0,
            "polymorphic_call_sites": 0,
            "max_targets": 0,
            Kind.STATIC: 0,
            Kind.VIRTUAL: 0,
            Kind.SPECIAL: 0,
            Kind.INTERFACE: 0,
        }
        for method in scene.get_methods():
            body = method.get_active_body()
            if body is None:
                continue
            for unit in body.units:
                invoke = unit.get_invoke_expr()
                if invoke is None:
                    continue
                stats["call_sites"] += 1
                kind, targets = self.resolve_call_site(scene, hierarchy, unit, invoke)
                stats[kind] = stats.get(kind, 0) + 1
                if targets:
                    stats["resolved_call_sites"] += 1
                else:
                    stats["phantom_call_sites"] += 1
                    phantom = scene.get_or_create_phantom_method(invoke.method_ref.signature)
                    targets = [phantom]
                    stats["phantom_edges"] += 1
                if len(targets) > 1:
                    stats["polymorphic_call_sites"] += 1
                stats["max_targets"] = max(stats["max_targets"], len(targets))
                for target in targets:
                    cg.add_edge(Edge(method, unit, target, kind))
        self.stats = stats
        scene.set_call_graph(cg)
        return cg

    # -- resolution ----------------------------------------------------------
    def resolve_call_site(
        self,
        scene: Scene,
        hierarchy: Hierarchy,
        unit: Unit,
        invoke: InvokeExpr,
    ) -> tuple[str, list[SootMethod]]:
        ref = invoke.get_method_ref()
        sub_sig = ref.get_sub_signature()
        declared = ref.declaring_class
        if isinstance(invoke, StaticInvokeExpr):
            target = hierarchy.resolve_static_dispatch(declared, sub_sig)
            return Kind.STATIC, [target] if target is not None else []
        if isinstance(invoke, SpecialInvokeExpr):
            target = hierarchy.resolve_special_dispatch(declared, sub_sig)
            return Kind.SPECIAL, [target] if target is not None else []
        kind = Kind.INTERFACE if isinstance(invoke, InterfaceInvokeExpr) else Kind.VIRTUAL
        receiver_type = self._receiver_type(hierarchy, invoke, declared)
        targets = hierarchy.resolve_abstract_dispatch(receiver_type, sub_sig)
        if not targets and receiver_type != declared:
            targets = hierarchy.resolve_abstract_dispatch(declared, sub_sig)
        return kind, targets

    @staticmethod
    def _receiver_type(hierarchy: Hierarchy, invoke: InvokeExpr, declared: str) -> str:
        """Refine the dispatch root with the static type of the receiver."""
        base = invoke.get_base()
        if base is None:
            return declared
        base_type = base.get_type()
        if base_type is None or base_type.is_primitive:
            return declared
        name = base_type.name
        if hierarchy.scene.get_soot_class_unsafe(name) is None:
            return declared
        if name == declared:
            return declared
        if hierarchy.is_sub_type_of(name, declared):
            return name
        return declared


def build_call_graph(scene: Scene | None = None) -> CallGraph:
    """Convenience wrapper around :class:`CHATransformer`."""
    return CHATransformer.v().transform(scene if scene is not None else Scene.v())


# ---------------------------------------------------------------------------
# Body transformers (the ``jtp`` pack)
# ---------------------------------------------------------------------------


def remove_units(body: JimpleBody, doomed: Iterable[Unit]) -> int:
    """Delete ``doomed`` from ``body``, retargeting branches to survivors."""
    doomed_uids = {u.uid for u in doomed}
    if not doomed_uids:
        return 0
    next_survivor: dict[int, Unit | None] = {}
    for index, unit in enumerate(body.units):
        if unit.uid not in doomed_uids:
            continue
        replacement: Unit | None = None
        for candidate in body.units[index + 1 :]:
            if candidate.uid not in doomed_uids:
                replacement = candidate
                break
        next_survivor[unit.uid] = replacement
    survivors = [u for u in body.units if u.uid not in doomed_uids]
    for unit in survivors:
        if isinstance(unit, BranchingStmt):
            retargeted: list[Unit] = []
            for target in unit.targets:
                resolved: Unit | None = target
                while resolved is not None and resolved.uid in doomed_uids:
                    resolved = next_survivor.get(resolved.uid)
                if resolved is not None:
                    retargeted.append(resolved)
            unit.targets = retargeted
        if isinstance(unit, IfStmt) and unit.false_target is not None:
            resolved = unit.false_target
            while resolved is not None and resolved.uid in doomed_uids:
                resolved = next_survivor.get(resolved.uid)
            unit.false_target = resolved
    removed = len(body.units) - len(survivors)
    body.units = survivors
    return removed


class BodyTransformer:
    """Base class of the intra-procedural passes."""

    phase_name = "jtp.transformer"

    def transform(
        self, body: JimpleBody | None, phase_name: str | None = None, options: dict | None = None
    ) -> dict[str, int]:
        if body is None:
            return {}
        return self.internal_transform(body, phase_name or self.phase_name, options or {})

    def internal_transform(
        self, body: JimpleBody, phase_name: str, options: dict
    ) -> dict[str, int]:  # pragma: no cover - overridden
        return {}

    def __str__(self) -> str:
        return "%s(%s)" % (type(self).__name__, self.phase_name)


class CopyPropagator(BodyTransformer):
    """Soot's ``jop.cp``: replace uses of copies with their source value.

    A use of ``x`` at unit ``u`` is rewritten when ``x`` has exactly one
    reaching definition ``x = y`` at ``u`` and ``y`` is either a constant or a
    local with a single definition in the whole body (which makes the rewrite
    trivially safe without needing full SSA).
    """

    phase_name = "jop.cp"
    max_iterations = 8

    def internal_transform(self, body: JimpleBody, phase_name: str, options: dict) -> dict[str, int]:
        propagate_constants = bool(options.get("propagate-constants", True))
        stats = {"locals_propagated": 0, "constants_propagated": 0, "iterations": 0}
        for _ in range(self.max_iterations):
            graph = BriefUnitGraph(body)
            local_defs = SimpleLocalDefs(graph)
            changed = 0
            for unit in graph:
                for local in unit.get_used_locals():
                    definitions = local_defs.get_defs_of_at(local, unit)
                    if len(definitions) != 1:
                        continue
                    definition = definitions[0]
                    if not isinstance(definition, AssignStmt):
                        continue  # never propagate @this / @parameter identities
                    if not isinstance(definition.left_op, Local):
                        continue
                    right = definition.right_op
                    if isinstance(right, Constant):
                        if not propagate_constants:
                            continue
                        replaced = unit.replace_use(local, right)
                        if replaced:
                            stats["constants_propagated"] += replaced
                            changed += replaced
                    elif isinstance(right, Local) and right.name != local.name:
                        if local_defs.def_count(right) > 1:
                            continue
                        replaced = unit.replace_use(local, right)
                        if replaced:
                            stats["locals_propagated"] += replaced
                            changed += replaced
            stats["iterations"] += 1
            if not changed:
                break
        return stats


class ConstantPropagatorAndFolder(BodyTransformer):
    """Fold binary expressions whose operands are both constants."""

    phase_name = "jop.cpf"

    _FOLDERS = {
        "+": lambda a, b: a + b,
        "-": lambda a, b: a - b,
        "*": lambda a, b: a * b,
    }

    def internal_transform(self, body: JimpleBody, phase_name: str, options: dict) -> dict[str, int]:
        folded = 0
        for unit in body.units:
            if not isinstance(unit, AssignStmt):
                continue
            right = unit.right_op
            if not isinstance(right, BinopExpr) or isinstance(right, ConditionExpr):
                continue
            op1, op2 = right.op1, right.op2
            folder = self._FOLDERS.get(right.symbol)
            if folder is None or not isinstance(op1, Constant) or not isinstance(op2, Constant):
                continue
            if not isinstance(op1.value, (int, float)) or not isinstance(op2.value, (int, float)):
                continue
            if isinstance(op1.value, bool) or isinstance(op2.value, bool):
                continue
            value = folder(op1.value, op2.value)
            unit.right_op = (
                IntConstant(int(value))
                if isinstance(value, int)
                else DoubleConstant(float(value))
            )
            folded += 1
        return {"expressions_folded": folded}


class DeadAssignmentEliminator(BodyTransformer):
    """Soot's ``jb.dae``: drop assignments to locals that are never read."""

    phase_name = "jb.dae"
    max_iterations = 8

    def internal_transform(self, body: JimpleBody, phase_name: str, options: dict) -> dict[str, int]:
        keep_invokes = bool(options.get("only-stack-locals", False)) is False
        stats = {"assignments_removed": 0, "iterations": 0}
        for _ in range(self.max_iterations):
            graph = BriefUnitGraph(body)
            live = SimpleLiveLocals(graph)
            doomed: list[Unit] = []
            for unit in body.units:
                if not isinstance(unit, AssignStmt) or isinstance(unit, IdentityStmt):
                    continue
                left = unit.left_op
                if not isinstance(left, Local):
                    continue  # stores to heap locations are always essential
                if left.name in live.get_live_locals_after(unit):
                    continue
                if keep_invokes and self._is_essential(unit.right_op):
                    continue
                doomed.append(unit)
            stats["iterations"] += 1
            if not doomed:
                break
            stats["assignments_removed"] += remove_units(body, doomed)
        return stats

    @staticmethod
    def _is_essential(value: Value) -> bool:
        """Invocations may have side effects and must never be dropped."""
        if isinstance(value, InvokeExpr):
            return True
        for nested in value.get_use_boxes():
            if isinstance(nested, InvokeExpr):
                return True
        return False


class UnreachableCodeEliminator(BodyTransformer):
    """Soot's ``jb.uce``: drop units not reachable from the body entry."""

    phase_name = "jb.uce"

    def internal_transform(self, body: JimpleBody, phase_name: str, options: dict) -> dict[str, int]:
        graph = ExceptionalUnitGraph(body)
        reachable = {u.uid for u in graph.get_reachable_units()}
        doomed = [u for u in body.units if u.uid not in reachable]
        removed = remove_units(body, doomed)
        return {"units_removed": removed}


class NopEliminator(BodyTransformer):
    """Soot's ``jb.ne``: drop ``nop`` units."""

    phase_name = "jb.ne"

    def internal_transform(self, body: JimpleBody, phase_name: str, options: dict) -> dict[str, int]:
        doomed = [u for u in body.units if isinstance(u, NopStmt)]
        return {"nops_removed": remove_units(body, doomed)}


class UnusedLocalEliminator(BodyTransformer):
    """Drop locals that no surviving unit mentions."""

    phase_name = "jb.ulp"

    def internal_transform(self, body: JimpleBody, phase_name: str, options: dict) -> dict[str, int]:
        mentioned: set[str] = set()
        for unit in body.units:
            for value in unit.get_def_boxes() + unit.get_use_boxes():
                for local in value.used_locals():
                    mentioned.add(local.name)
        kept = [
            local
            for local in body.locals
            if local.name in mentioned
            or (body.this_local is not None and local.name == body.this_local.name)
            or any(local.name == p.name for p in body.param_locals)
        ]
        removed = len(body.locals) - len(kept)
        body.locals = kept
        return {"locals_removed": removed}


class Transform:
    """A named phase wrapping one :class:`BodyTransformer`."""

    def __init__(self, phase_name: str, transformer: BodyTransformer) -> None:
        self.phase_name = phase_name
        self.transformer = transformer
        self.options: dict[str, Any] = {}

    def apply(self, body: JimpleBody) -> dict[str, int]:
        return self.transformer.transform(body, self.phase_name, self.options)

    def __str__(self) -> str:
        return "Transform(%s)" % self.phase_name


class Pack:
    """An ordered collection of :class:`Transform` phases."""

    def __init__(self, name: str) -> None:
        self.name = name
        self.transforms: list[Transform] = []

    def add(self, transform: Transform) -> Transform:
        self.transforms.append(transform)
        return transform

    def get_transform(self, phase_name: str) -> Transform | None:
        for transform in self.transforms:
            if transform.phase_name == phase_name:
                return transform
        return None

    def apply(self, body: JimpleBody) -> dict[str, dict[str, int]]:
        results: dict[str, dict[str, int]] = {}
        for transform in self.transforms:
            results[transform.phase_name] = transform.apply(body)
        return results

    def __iter__(self) -> Iterator[Transform]:
        return iter(self.transforms)

    def __len__(self) -> int:
        return len(self.transforms)

    def __str__(self) -> str:
        return "Pack(%s, phases=%d)" % (self.name, len(self.transforms))


class PackManager:
    """Holds the standard packs and runs them over a scene."""

    _instance: "PackManager | None" = None

    def __init__(self) -> None:
        self.packs: dict[str, Pack] = {}
        self._install_default_packs()

    @classmethod
    def v(cls) -> "PackManager":
        if cls._instance is None:
            cls._instance = PackManager()
        return cls._instance

    @classmethod
    def reset(cls) -> "PackManager":
        cls._instance = PackManager()
        return cls._instance

    def _install_default_packs(self) -> None:
        jb = Pack("jb")
        jb.add(Transform("jb.uce", UnreachableCodeEliminator()))
        jb.add(Transform("jb.ne", NopEliminator()))
        self.packs["jb"] = jb

        jop = Pack("jop")
        jop.add(Transform("jop.cpf", ConstantPropagatorAndFolder()))
        jop.add(Transform("jop.cp", CopyPropagator()))
        jop.add(Transform("jop.dae", DeadAssignmentEliminator()))
        jop.add(Transform("jop.ule", UnusedLocalEliminator()))
        self.packs["jop"] = jop

        self.packs["jtp"] = Pack("jtp")
        self.packs["wjtp"] = Pack("wjtp")
        self.packs["cg"] = Pack("cg")

    def get_pack(self, name: str) -> Pack:
        pack = self.packs.get(name)
        if pack is None:
            pack = Pack(name)
            self.packs[name] = pack
        return pack

    def has_pack(self, name: str) -> bool:
        return name in self.packs

    def run_body_packs(self, scene: Scene | None = None) -> dict[str, int]:
        """Run ``jb`` then ``jop`` over every concrete body in the scene."""
        scene = scene if scene is not None else Scene.v()
        totals: dict[str, int] = {}
        for method in scene.get_methods():
            body = method.get_active_body()
            if body is None:
                continue
            for pack_name in ("jb", "jop"):
                for phase, result in self.get_pack(pack_name).apply(body).items():
                    for key, value in result.items():
                        totals[key] = totals.get(key, 0) + value
        return totals

